<?phpfunction dump($param) {    if ($_SERVER['REMOTE_ADDR'] == '217.25.227.230') {        echo '<pre style="color:red;font-size:14px">';        print_r($param);        echo '</pre>';    }}function detectMobile() {    //http://detectmobilebrowsers.com/mobile    $useragent = $_SERVER['HTTP_USER_AGENT'];    if (preg_match('/(android|bb\d+|meego).+mobile|avantgo|bada\/|blackberry|blazer|compal|elaine|fennec|hiptop|iemobile|ip(hone|od)|iris|kindle|lge |maemo|midp|mmp|mobile.+firefox|netfront|opera m(ob|in)i|palm( os)?|phone|p(ixi|re)\/|plucker|pocket|psp|series(4|6)0|symbian|treo|up\.(browser|link)|vodafone|wap|windows ce|xda|xiino/i', $useragent) || preg_match('/1207|6310|6590|3gso|4thp|50[1-6]i|770s|802s|a wa|abac|ac(er|oo|s\-)|ai(ko|rn)|al(av|ca|co)|amoi|an(ex|ny|yw)|aptu|ar(ch|go)|as(te|us)|attw|au(di|\-m|r |s )|avan|be(ck|ll|nq)|bi(lb|rd)|bl(ac|az)|br(e|v)w|bumb|bw\-(n|u)|c55\/|capi|ccwa|cdm\-|cell|chtm|cldc|cmd\-|co(mp|nd)|craw|da(it|ll|ng)|dbte|dc\-s|devi|dica|dmob|do(c|p)o|ds(12|\-d)|el(49|ai)|em(l2|ul)|er(ic|k0)|esl8|ez([4-7]0|os|wa|ze)|fetc|fly(\-|_)|g1 u|g560|gene|gf\-5|g\-mo|go(\.w|od)|gr(ad|un)|haie|hcit|hd\-(m|p|t)|hei\-|hi(pt|ta)|hp( i|ip)|hs\-c|ht(c(\-| |_|a|g|p|s|t)|tp)|hu(aw|tc)|i\-(20|go|ma)|i230|iac( |\-|\/)|ibro|idea|ig01|ikom|im1k|inno|ipaq|iris|ja(t|v)a|jbro|jemu|jigs|kddi|keji|kgt( |\/)|klon|kpt |kwc\-|kyo(c|k)|le(no|xi)|lg( g|\/(k|l|u)|50|54|\-[a-w])|libw|lynx|m1\-w|m3ga|m50\/|ma(te|ui|xo)|mc(01|21|ca)|m\-cr|me(rc|ri)|mi(o8|oa|ts)|mmef|mo(01|02|bi|de|do|t(\-| |o|v)|zz)|mt(50|p1|v )|mwbp|mywa|n10[0-2]|n20[2-3]|n30(0|2)|n50(0|2|5)|n7(0(0|1)|10)|ne((c|m)\-|on|tf|wf|wg|wt)|nok(6|i)|nzph|o2im|op(ti|wv)|oran|owg1|p800|pan(a|d|t)|pdxg|pg(13|\-([1-8]|c))|phil|pire|pl(ay|uc)|pn\-2|po(ck|rt|se)|prox|psio|pt\-g|qa\-a|qc(07|12|21|32|60|\-[2-7]|i\-)|qtek|r380|r600|raks|rim9|ro(ve|zo)|s55\/|sa(ge|ma|mm|ms|ny|va)|sc(01|h\-|oo|p\-)|sdk\/|se(c(\-|0|1)|47|mc|nd|ri)|sgh\-|shar|sie(\-|m)|sk\-0|sl(45|id)|sm(al|ar|b3|it|t5)|so(ft|ny)|sp(01|h\-|v\-|v )|sy(01|mb)|t2(18|50)|t6(00|10|18)|ta(gt|lk)|tcl\-|tdg\-|tel(i|m)|tim\-|t\-mo|to(pl|sh)|ts(70|m\-|m3|m5)|tx\-9|up(\.b|g1|si)|utst|v400|v750|veri|vi(rg|te)|vk(40|5[0-3]|\-v)|vm40|voda|vulc|vx(52|53|60|61|70|80|81|83|85|98)|w3c(\-| )|webc|whit|wi(g |nc|nw)|wmlb|wonu|x700|yas\-|your|zeto|zte\-/i', substr($useragent, 0, 4))) {        return true;    } else {        return false;    }}function getOS() {    $user_agent = $_SERVER['HTTP_USER_AGENT'];    $os_platform = "Unknown OS Platform";    $os_array = array(        '/windows nt 10/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 10'],        '/windows nt 6.3/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 8.1'],        '/windows nt 6.2/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 8'],        '/windows nt 6.1/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 7'],        '/windows nt 6.0/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows Vista'],        '/windows nt 5.2/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows Server 2003/XP x64'],        '/windows nt 5.1/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows XP'],        '/windows xp/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows XP'],        '/windows nt 5.0/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 2000'],        '/windows me/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows ME'],        '/win98/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 98'],        '/win95/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 95'],        '/win16/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Windows 3.11'],        '/macintosh|mac os x/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Mac OS X'],        '/mac_powerpc/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Mac OS 9'],        '/linux/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Linux'],        '/ubuntu/i' => ['type' => '', 'family' => '', 'platform' => 'desktop', 'name' => 'Ubuntu'],        '/iphone/i' => ['type' => '', 'family' => '', 'platform' => 'iPhone', 'name' => 'iPhone'],        '/ipod/i' => ['type' => '', 'family' => '', 'platform' => 'iPhone', 'name' => 'iPod'],        '/ipad/i' => ['type' => '', 'family' => '', 'platform' => 'iPhone', 'name' => 'iPad'],        '/android/i' => ['type' => '', 'family' => '', 'platform' => 'android', 'name' => 'Android'],        '/blackberry/i' => 'BlackBerry',        '/webos/i' => 'Mobile'    );    foreach ($os_array as $regex => $value) {        if (preg_match($regex, $user_agent)) {            $os_platform = $value;        }    }    return $os_platform;}function str_replace_once($search, $replace, $text) {    $pos = strpos($text, $search);    return $pos !== false ? substr_replace($text, $replace, $pos, strlen($search)) : $text;}function getPhoneLink($phone) {    $phone = str_replace([' ', '(', ')', '-', ' '], '', $phone);    if (stripos($phone, '+7') === false && stripos($phone, '8800') === false) {        if (stripos($phone, '8') === 0) {            return '' . $phone;            ;        }        return '+7' . $phone;    } else {        return '' . $phone;    }}function getFileExt($fileSrc) {    return end(explode('.', $fileSrc));}function getFileIco($fileSrc) {    $ext = mb_strtolower(end(explode('.', $fileSrc)));    if (in_array($ext, ['doc', 'docx', 'rft', 'odt'])) {        return '/local/templates/juno/img/docIcoDoc.svg';    } else if (in_array($ext, ['pdf'])) {        return '/local/templates/juno/img/docIcoPDF.svg';    } else {        return '/local/templates/juno/img/docIcoFile.svg';    }}function getFileSize($filePath, $decimals = 2) {    $bytes = filesize($_SERVER['DOCUMENT_ROOT'] . $filePath);    $sz = ['Байт', 'Кб', 'Мб', 'Гб', 'Тб', 'Пб'];    $factor = floor((strlen($bytes) - 1) / 3);    return sprintf("%.{$decimals}f", $bytes / pow(1024, $factor)) . @$sz[$factor];}// меняем размер файла на летуfunction getResizeImgSrc($idImg, $w, $h) {    $renderImage = CFile::ResizeImageGet($idImg, ["width" => $w, "height" => $h], BX_RESIZE_IMAGE_EXACT);    return $renderImage['src'];}function getResizeImgSrcProportional($idImg, $w, $h) {    $renderImage = CFile::ResizeImageGet($idImg, ["width" => $w, "height" => $h], BX_RESIZE_IMAGE_PROPORTIONALDETAIL_PICTURE);    return $renderImage['src'];}// меняем размер файла на лету END// Получить элемент по его IDfunction getElementById($iblockId, $elementId) {    if (!CModule::IncludeModule("iblock")) {        return;    }    $arSelect = array("ID", "NAME", "IBLOCK_ID", 'PREVIEW_PICTURE', "PREVIEW_TEXT", "DETAIL_TEXT", "DETAIL_PAGE_URL", "PROPERTIES_*");    $arFilter = array('IBLOCK_ID' => $iblockId, 'ID' => $elementId, 'ACTIVE' => 'Y', 'SECTION_ACTIVE');    $res = CIBlockElement::GetList(Array("SORT" => "ASC"), $arFilter, false, false, $arSelect);    $arElementFiedls = array();    if ($ob = $res->GetNextElement())        $arElementFiedls = array_merge($ob->GetFields(), $ob->GetProperties());    return $arElementFiedls;}// Получить элемент по его ID END// Получить список элементов инфоблокаfunction getElemensList($iblockId, $isProperties = true, $order = ["SORT" => "ASC"]) {    if (!CModule::IncludeModule("iblock")) {        return;    }    $arSelect = array("ID", "NAME", "IBLOCK_ID", "PREVIEW_TEXT", "DETAIL_TEXT", "DETAIL_PAGE_URL", 'PREVIEW_PICTURE', 'DETAIL_PICTURE', "PROPERTIES_*");    $arFilter = array('IBLOCK_ID' => $iblockId, 'ACTIVE' => 'Y');    $res = CIBlockElement::GetList($order, $arFilter, false, ($pageSize != '' ? ['nPageSize' => $pageSize] : false), $arSelect);    $arElements = array();    while ($ob = $res->GetNextElement()) {        $arElements[] = array_merge($ob->GetFields(), $ob->GetProperties());    } // while    return $arElements;}function getElemensList2($iblockId, $isProperties = true, $order = ["SORT" => "ASC"], $sectionCode = '', $pageSize = '', $sectionId = '') {    if (!CModule::IncludeModule("iblock")) {        return;    }    $arSelect = array("ID", "NAME", "IBLOCK_ID", "PREVIEW_TEXT", "DETAIL_TEXT", "DETAIL_PAGE_URL", 'PREVIEW_PICTURE', 'DETAIL_PICTURE', "PROPERTIES_*");    $arFilter = array('IBLOCK_ID' => $iblockId, 'ACTIVE' => 'Y', 'SECTION_CODE' => $sectionCode, 'SECTION_ID' => $sectionId);    $res = CIBlockElement::GetList($order, $arFilter, false, ($pageSize != '' ? ['nPageSize' => $pageSize] : false), $arSelect);    $arElements = array();    while ($ob = $res->GetNextElement()) {        if ($isProperties)            $arElements[] = array_merge($ob->GetFields(), $ob->GetProperties());        else            $arElements[] = $ob->GetFields();    } // while    return $arElements;}// Получить список элементов инфоблока END// Получить раздел по его IDfunction getSectionById($sectionId, $iblockId) {    $arSelect = array("ID", "NAME", "SECTION_PAGE_URL", "IBLOCK_SECTION_ID", "DESCRIPTION", "IBLOCK_ID", "UF_*");    $arFilter = array('IBLOCK_ID' => $iblockId, 'ID' => $sectionId, 'ACTIVE' => 'Y');    $rsSect = CIBlockSection::GetList(array("SORT" => "ASC"), $arFilter, false, $arSelect);    $arSectionFiedls = array();    if ($arSect = $rsSect->GetNext())        $arSectionFiedls = $arSect;    return $arSectionFiedls;}function getSectionList($iblockId, $depthLevel = '', $sectionId = '', $leftMargin = '') {    if (!CModule::IncludeModule("iblock")) {        return;    }    $arSelect = array("ID", "NAME", "SECTION_PAGE_URL", "IBLOCK_SECTION_ID", "DESCRIPTION", "IBLOCK_ID", "UF_*");    $arFilter = array('IBLOCK_ID' => $iblockId, 'ID' => $sectionId, 'ACTIVE' => 'Y', 'DEPTH_LEVEL' => $depthLevel);    $rsSect = CIBlockSection::GetList(array("SORT" => "ASC"), $arFilter, false, $arSelect);    $arSectionFiedls = array();    while ($arSect = $rsSect->GetNext()) {        $arElements[] = $arSect;    }    return $arElements;}// getSectionById// Получить разделыfunction getIblockSections($iblockId, string $code = '', string $id = '') {    $arSelect = array("ID", "NAME", "SECTION_PAGE_URL", "IBLOCK_SECTION_ID", "DESCRIPTION", "IBLOCK_ID", "UF_*");    $arFilter = array('IBLOCK_ID' => $iblockId, 'ID' => '', 'ACTIVE' => 'Y', 'CODE' => $code, 'ID' => $id);    $rsSect = CIBlockSection::GetList(array("SORT" => "ASC"), $arFilter, false, $arSelect);    $arSectionFiedls = array();//    if ($arSect = $rsSect->GetNext()) {//        $arSectionFiedls = $arSect;//    }    while ($ob = $rsSect->GetNextElement()) {        $arElements[] = $ob;    }    // while    return $arElements;}function getSiteUrl() {    $protocol = $_SERVER['HTTPS'] != '' ? 'https://' : 'http://';    return $protocol . $_SERVER['SERVER_NAME'];}function getCurrentUrl() {    return getSiteUrl() . $_SERVER['REQUEST_URI'];}function getItemDate($arItem) {    return (!empty($arItem["DATE_ACTIVE_FROM"]) ?            CIBlockFormatProperties::DateFormat("j F Y", MakeTimeStamp($arItem["DATE_ACTIVE_FROM"], CSite::GetDateFormat())) :            CIBlockFormatProperties::DateFormat("j F Y", MakeTimeStamp($arItem["DATE_CREATE"], CSite::GetDateFormat())));}function getIblockById($id) {    $res = CIBlock::GetByID($id);    if ($ar_res = $res->GetNext()) {        return $ar_res;    }}function getElementByCode($iblock, $code) {    $arSelect = array("ID", "NAME", "IBLOCK_ID", "PREVIEW_TEXT", "DETAIL_TEXT", "DETAIL_PAGE_URL", 'PREVIEW_PICTURE', 'DETAIL_PICTURE', "PROPERTIES_*");    $arFilter = array('IBLOCK_ID' => $iblock, 'ACTIVE' => 'Y', 'CODE' => $code);    $res = CIBlockElement::GetList($order, $arFilter, false, false, $arSelect);    $arElements = array();    if ($ob = $res->GetNextElement()) {        return array_merge($ob->GetFields(), $ob->GetProperties());    }}function getObjLink($iblockId, $objId) {    $arSelect = array("ID", "NAME", "IBLOCK_ID", 'ACTIVE_FROM', 'DATE_ACTIVE_FROM', 'DATE_CREATE', "PREVIEW_TEXT", "DETAIL_TEXT", "DETAIL_PAGE_URL", 'PREVIEW_PICTURE', 'DETAIL_PICTURE', "PROPERTIES_*");    $arFilter = array('IBLOCK_ID' => $iblockId, 'ACTIVE' => 'Y', 'PROPERTY_OBJ_LINK.ID' => $objId);    $res = CIBlockElement::GetList('', $arFilter, false, false, $arSelect);    $resArr = array();    while ($ob = $res->GetNextElement()) {        $resArr[] = array_merge($ob->GetFields(), $ob->GetProperties());    }    return $resArr;}